package scaffolds

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// BannerLintRoot walks templates under root and verifies that each one
// carries the lifecycle banner appropriate for its tier:
//
//   - Tier 1 (machine-only, regenerated every run, gitignored) MUST carry
//     the canonical "Code generated by forge. DO NOT EDIT." line (followed
//     by the "forge-owned: regenerated every run — do not edit (forge
//     disown to take ownership)" line) in the first ~30 lines. Examples:
//     `*_gen.go.tmpl`, `_gen.ts.tmpl`, `*_gen.yml.tmpl`, frontend hooks.
//   - Tier 2 (one-shot scaffolds the user owns after first emit) MUST
//     carry the canonical "yours: scaffolded once, never touched again —
//     forge will not overwrite this file" line. Examples:
//     `internal-package/contract.go.tmpl`, `frontend/pages/*.tsx.tmpl`.
//   - Tier 3 (user-owned skeletons like `providers.go.tmpl`, `forge.yaml`,
//     starter `cmd/*.go` files) is intentionally banner-less — `//forge:allow`
//     is the existing user-owned marker and is enforced by other linters.
//
// The walk only visits template files under `internal/templates/`, so
// running `forge lint --banners` from outside the forge repo is a no-op.
//
// Tier classification is filename-based — see classifyTemplate. Files
// with names that don't slot cleanly into a tier are reported as
// `banner-unclassified` warnings; that's a hint to either bring the
// template into one of the three tiers or to expand the skip-list below.
func BannerLintRoot(root string) (Result, error) {
	var result Result

	templateRoots := []string{
		filepath.Join(root, "internal", "templates"),
	}

	for _, troot := range templateRoots {
		if _, err := os.Stat(troot); os.IsNotExist(err) {
			// Outside the forge repo there is no template tree — silently
			// skip rather than emit confusing "no findings" output.
			continue
		}
		err := filepath.WalkDir(troot, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				if shouldSkipDir(d.Name()) {
					return filepath.SkipDir
				}
				return nil
			}
			if !strings.HasSuffix(path, ".tmpl") {
				return nil
			}
			findings, ferr := lintTemplateBanner(path, root)
			if ferr != nil {
				return ferr
			}
			result.Findings = append(result.Findings, findings...)
			return nil
		})
		if err != nil {
			return result, err
		}
	}

	return result, nil
}

// templateTier captures which lifecycle bucket a template emits into.
type templateTier int

const (
	tierUnclassified templateTier = iota
	tier1Generated                // _gen / regenerated every run
	tier2Scaffold                 // one-shot scaffold, user owns after emit
	tier3UserOwned                // user-owned skeleton; banner-less by design
	tierSkip                      // by-nature banner-less (Makefile, package.json, env files, etc.)
)

// lintTemplateBanner classifies path and emits findings if the required
// banner is missing.
//
// Classification is content-first: a template that already carries the
// canonical Tier-1 banner is treated as Tier 1 regardless of filename
// (some regenerated files have non-`_gen.*` names but ship with the
// canonical header). The same content-first rule applies to Tier-2
// markers. If neither marker is present, fall back to name-based
// classification.
func lintTemplateBanner(path, root string) ([]Finding, error) {
	rel := relPath(path, root)

	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	// Window is generous enough (60 lines) to cover scaffolds whose
	// canonical banner sits below a long doc-comment preamble — e.g.
	// `providers.go.tmpl` documents the owned-Infra pattern in 40+
	// lines of //-comments before declaring the canonical "yours:" banner.
	head := firstLines(data, 60)

	// Content-first overrides:
	//   - the file already declares its tier via the canonical banner,
	//     so the lint has nothing to flag.
	//   - `//forge:allow` is the canonical user-owned (Tier-3) marker. Its
	//     presence means the template is intentionally banner-less and
	//     hand-edited by the user after first emit (e.g. `app_extras.go`,
	//     `setup.go`). Treat it as a content-first Tier-3 override so a
	//     new user-owned scaffold doesn't have to be added to the
	//     classifyTemplate name list before the warning quiets down.
	if declaresGeneratedBanner(head) || declaresScaffoldOnceBanner(head) || declaresUserOwnedMarker(head) {
		return nil, nil
	}

	// Banner is absent — fall back to name-based classification to decide
	// whether the absence is a finding.
	tier := classifyTemplate(rel)

	switch tier {
	case tierSkip, tier3UserOwned:
		return nil, nil
	case tier1Generated:
		return []Finding{{
			Rule:     "banner-tier1-missing-generated-header",
			Severity: SeverityWarning,
			Path:     rel,
			Message:  `Tier-1 template (regenerated every run) is missing the canonical "Code generated by forge. DO NOT EDIT." banner in its first ~30 lines`,
		}}, nil
	case tier2Scaffold:
		return []Finding{{
			Rule:     "banner-tier2-missing-scaffold-header",
			Severity: SeverityWarning,
			Path:     rel,
			Message:  `Tier-2 template (one-shot scaffold) is missing the canonical "yours: scaffolded once, never touched again — forge will not overwrite this file" banner; users won't know forge writes the file once and never overwrites it`,
		}}, nil
	case tierUnclassified:
		return []Finding{{
			Rule:     "banner-unclassified",
			Severity: SeverityWarning,
			Path:     rel,
			Message:  "template name does not match any known tier classification — extend banners.go's classifyTemplate or skip-list, or rename to fit a known pattern (_gen.* for regenerated, _scaffold for one-shot)",
		}}, nil
	}
	return nil, nil
}

// The three canonical lifecycle markers a template can carry in its head.
// Named predicates because two lints read them: the banner lint (which asks
// "is the required banner present?") and the cross-tier lint (which asks
// "which tier does this template declare itself into?" — see
// resolveTemplateTier in cross_tier.go).

// declaresGeneratedBanner reports whether the head carries the Tier-1
// "Code generated by forge. DO NOT EDIT." marker.
func declaresGeneratedBanner(head string) bool {
	return strings.Contains(head, "Code generated")
}

// declaresScaffoldOnceBanner reports whether the head carries the canonical
// Tier-2 "yours: scaffolded once, never touched again" marker.
func declaresScaffoldOnceBanner(head string) bool {
	return strings.Contains(head, "yours: scaffolded once")
}

// declaresUserOwnedMarker reports whether the head carries `//forge:allow`,
// the canonical Tier-3 user-owned marker.
func declaresUserOwnedMarker(head string) bool {
	return strings.Contains(head, "forge:allow")
}

// classifyTemplate buckets a template by its on-disk name + path.
//
// The classifier is intentionally explicit: every known Tier-1 / Tier-2 /
// Tier-3 template is matched by an explicit suffix or path-fragment so
// that a new template added later doesn't silently fall into
// `tierUnclassified` and produce a noisy warning until someone updates
// this map. The "false-positive cost" here is real because lint findings
// are surfaced as advisory output during `forge lint` — every spurious
// warning trains the user to ignore them.
func classifyTemplate(rel string) templateTier {
	base := filepath.Base(rel)
	noTmpl := strings.TrimSuffix(base, ".tmpl")

	// 1) Skip-list: templates that are by-nature banner-less.
	if isSkippedTemplate(noTmpl) {
		return tierSkip
	}

	// 2) Tier 1: _gen.<ext> in the basename, OR an explicit listed
	// regenerated file (cmd-server.go, cmd-cli-main.go, bootstrap*, etc).
	if isGenSuffix(noTmpl) {
		return tier1Generated
	}
	if isKnownTier1(rel, noTmpl) {
		return tier1Generated
	}

	// 3) Tier 2: explicit one-shot scaffolds.
	if isKnownTier2(rel, noTmpl) {
		return tier2Scaffold
	}

	// 4) Tier 3: user-owned skeletons by name.
	if isKnownTier3(rel, noTmpl) {
		return tier3UserOwned
	}

	return tierUnclassified
}

// isSkippedTemplate returns true for templates whose nature precludes a
// header banner: Makefile preamble, .gitignore, language manifests, env
// files, JSON-only configs, etc.
func isSkippedTemplate(noTmpl string) bool {
	switch noTmpl {
	case "Makefile",
		// handlers_crud_shim_method.go.tmpl is a method-body FRAGMENT
		// appended into the user-owned handlers_crud.go — it is not a
		// standalone file and carries no file header of its own.
		"handlers_crud_shim_method.go",
		// handlers_methods.go.tmpl is likewise a method FRAGMENT: forge
		// renders one handler stub per RPC and appends them into the
		// user-owned handlers.go scaffold. It carries per-method
		// FORGE_SCAFFOLD markers but no file header of its own, so it is
		// neither a regenerated `_gen` file nor a standalone `_scaffold`.
		"handlers_methods.go",
		// Tool manifests / infra config without a natural banner slot.
		"buf.yaml",
		"traefik.yaml",
		".gitignore",
		".gitattributes",
		".dockerignore",
		"Dockerfile",
		"Taskfile.yml",
		"Taskfile.cli.yml",
		"Taskfile.library.yml",
		"go.mod",
		"go.mod.cli",
		"go.mod.library",
		"gen-go.mod",
		"go.work",
		"package.json",
		"app.json",
		"buf.gen.yaml",
		"mcp.json",
		"mcp.json.example",
		"vscode-launch.json",
		"vscode-launch.cli.json",
		"vscode-launch.library.json",
		"k3d.yaml",
		"docker-compose.e2e.yml",
		"kcl.mod",
		"air.toml",
		"air-debug.toml",
		"next.config.ts",
		"reliant.md":
		return true
	}
	return false
}

// isGenSuffix matches `*_gen.<ext>` for the languages forge emits.
func isGenSuffix(name string) bool {
	for _, suffix := range []string{
		"_gen.go",
		"_gen.ts",
		"_gen.tsx",
		"_gen.k",
		"_gen.yml",
		"_gen.yaml",
		"_gen.sql",
		"_gen.md",
	} {
		if strings.HasSuffix(name, suffix) {
			return true
		}
	}
	return false
}

// isKnownTier1 lists templates that are regenerated every `forge generate`
// run but don't carry a `_gen.*` suffix (legacy naming, special files).
func isKnownTier1(rel, noTmpl string) bool {
	// Frontend mocks and hooks: regenerated from the proto descriptor each
	// run. These templates render to `*_gen.*` FILES (mock-transport_gen.ts,
	// otel_gen.ts, <svc>-service-hooks_gen.ts, …); it is only the template
	// names here that still lack the suffix, because a template's name
	// describes the module it renders, not the tier of the render.
	if strings.HasSuffix(rel, "frontend/hooks.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/mocks/mock-data.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/mocks/mock-transport.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/mocks/scenarios/scenario-types.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/mocks/scenarios/scenarios-index.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/nextjs/src/lib/otel_gen.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/vite-spa/src/lib/otel_gen.ts.tmpl") {
		return true
	}
	// Project-level cmd/ scaffolds: regenerated; they carry the canonical header.
	switch noTmpl {
	case "cmd-cli-main.go", "cmd-cli-version.go",
		// The cmd/<bin>/ command tree (devspace idiom): the package-cmd tree
		// files, the per-service item file, and the three group anchors. All
		// go through writeForgeOwned (internal/codegen/writers.go) — they are
		// regenerated every run and carry the canonical header.
		//
		// The composition root (cmd-main.go), the four decision files of the
		// command tree (cmd-tree-serve.go, cmd-tree-server.go,
		// cmd-tree-version.go, cmd-tree-db.go), and the per-worker/
		// per-operator subcommand items (cmd-worker-group.go /
		// cmd-operator-group.go) are deliberately NOT here:
		// writeForgeScaffoldOnce writes them once and never overwrites them,
		// which makes them one-shot scaffolds (see isKnownTier2). Certifying
		// them Tier-1 asked their authors to stamp a "regenerated every run —
		// do not edit" banner on files forge never regenerates.
		//
		// The command tree has NO Tier-1 file: cmd-tree-root-gen.go is
		// retired. Its three facts either stopped being re-derived
		// (ServiceName, fixed at scaffold; the `db` command, wired directly
		// in the scaffold-rendered root.go) or moved to the package they are
		// a fact about (the embedded migration set → db.Source()).
		// cmd-tree-root.go — the tree's shape and flags — is scaffold-once
		// and belongs to the user, as does cmd-svc-group.go; the mount
		// expression the latter calls is re-derived next door in
		// cmd-svc-mount-gen.go, because a collision rename can change its
		// spelling after the service is born.
		"cmd-svc-mount-gen.go",
		// cmd-component-accessor-gen.go is the same split for a per-worker /
		// per-operator subcommand: the accessor binding it runs, re-derived
		// from whether internal/app declares the accessor yet.
		"cmd-component-accessor-gen.go",
		"cmd-svc-register.go",
		"cmd-worker-register.go", "cmd-operator-register.go",
		// internal/app/mounts_services.go — the HTTP-mount surface, a pure
		// projection of the discovered service set (writeForgeOwned).
		"mounts_services_gen.go":
		return true
	// NB: migrate.go is gone, not merely unlisted. It was 86 lines of
	// golang-migrate ceremony with one project-specific token in it
	// (forgedb.MigrationsFS) — library code parked in the user's tree — and
	// now lives in pkg/migratekit.AutoMigrate.
	case "bootstrap.go", "bootstrap_testing.go",
		"config.go",
		"alloy-config.alloy":
		return true
	}
	// NB: CI workflows (ci.yml, deploy.yml, build-images.yml, e2e.yml,
	// proto-breaking.yml, dependabot.yml) are NOT Tier-1 — they are
	// write-once scaffolds the user owns (see isKnownTier2). Certifying
	// them Tier-1 mis-flagged sanctioned hand-edits as drift.
	return false
}

// isKnownTier2 lists one-shot scaffolds: forge writes them once and never
// overwrites them after the first emit.
func isKnownTier2(rel, noTmpl string) bool {
	// internal-package scaffolds (pkg new flow + adapter/eventbus/client flavors).
	if strings.Contains(rel, "internal/templates/internal-package/") {
		switch noTmpl {
		case "service.go", "contract.go", "contract_test.go",
			"client.go", "client_test.go",
			"service_test.go",
			"adapter.go", "adapter_test.go", "cache.go":
			return true
		}
	}
	// The command tree + component WIRING: the composition root, the
	// per-worker/per-operator subcommand items, and the internal/app
	// composition pair. writeForgeScaffoldOnce emits each exactly once, when
	// it does not yet exist, and never rewrites it — from that point the user
	// owns the bytes (adding a component is a hand-edit or a `forge project
	// add` append, never a re-derivation).
	switch noTmpl {
	case "cmd-main.go", "cmd-worker-group.go", "cmd-operator-group.go",
		// The four command-tree files whose every statement is a DECISION
		// the application owns, so the user owns the bytes from birth. Each
		// one's invariant half lives in a forge library, which is what keeps
		// an owned copy on the upgrade path instead of stranding it:
		//
		//   - cmd-tree-serve.go   the serve pipeline (fail-closed auth
		//                         posture, interceptor order, payload caps,
		//                         CORS policy, readiness set, teardown)
		//                         → pkg/serverkit
		//   - cmd-tree-server.go  the all-services ServeSpec: what this
		//                         process mounts and supervises, and whether
		//                         an unmounted declared service fails boot
		//                         → pkg/serverkit (nothing left to extract)
		//   - cmd-tree-version.go the ldflags-stamped variables; `-X` targets
		//                         a variable by package path, so these must
		//                         live in the project → pkg/cmdkit
		//   - cmd-tree-db.go      migration policy: dirty-schema fail-hard vs
		//                         auto-force, is "nothing pending" success
		//                         → pkg/migratekit
		//   - cmd-tree-root.go    the command tree's shape: its flags, its
		//                         Deps struct, which commands hang off the
		//                         root, and ServiceName. The one derived
		//                         migration fact lives in db.Source()
		//                         → pkg/cmdkit
		//   - cmd-svc-group.go    one service's subcommand — its flags, its
		//                         RunE, its help text. The typed mount
		//                         expression it calls is re-derived next
		//                         door in cmd-svc-mount-gen.go
		"cmd-tree-serve.go", "cmd-tree-server.go",
		"cmd-tree-version.go", "cmd-tree-db.go", "cmd-tree-metrics.go",
		"internal-metrics.go",
		"cmd-tree-root.go", "cmd-svc-group.go",
		"compose.go", "lifecycle.go":
		return true
	}
	// Binary scaffolds (forge scaffold binary flow): cobra subcommand + the
	// internal/<name>/ runtime trio. Classified as one-shot because the
	// user owns Run's body and contract.go's Deps from emission onward.
	if strings.Contains(rel, "internal/templates/project/binary/") {
		switch noTmpl {
		case "cmd-binary.go", "binary.go", "binary_test.go", "contract.go", "contract_test.go":
			return true
		}
	}
	// Frontend page scaffolds (forge scaffold page).
	if strings.Contains(rel, "internal/templates/frontend/pages/") {
		return true
	}
	// Frontend scenario scaffolds (forge scaffold scenario + first-time emit of
	// the empty default). default-scenario.ts.tmpl is seeded once and then
	// hand-editable; scenario.ts.tmpl produces the per-scenario file written
	// at `forge scaffold scenario` time.
	if strings.HasSuffix(rel, "frontend/mocks/scenarios/default-scenario.ts.tmpl") ||
		strings.HasSuffix(rel, "frontend/mocks/scenarios/scenario.ts.tmpl") {
		return true
	}
	// Service-package one-shot tests and user-owned CRUD scaffolds
	// (owned from line one). handlers_crud_shim_method.go is NOT here —
	// it's a method-body fragment, skip-listed above.
	switch noTmpl {
	case "unit_test.go",
		"handlers_crud_test.go",
		"handlers_crud.go":
		return true
	}
	// CI starter files that ship a default the user is expected to review
	// and own: CODEOWNERS, plus the GitHub Actions workflows + dependabot.
	// Forge writes these once (WriteScaffoldIfMissing) and never stomps
	// edits — they carry the "yours: scaffolded once" banner, not a
	// forge:hash marker, so hand-edits are sanctioned, not drift.
	if strings.HasPrefix(rel, "internal/templates/ci/") {
		switch noTmpl {
		case "CODEOWNERS",
			"ci.yml", "deploy.yml", "build-images.yml", "e2e.yml",
			"proto-breaking.yml", "dependabot.yml":
			return true
		}
	}
	return false
}

// isKnownTier3 lists user-owned skeletons that are intentionally
// banner-less (the user's `//forge:allow` and contract.go conventions
// are checked by other analyzers).
func isKnownTier3(rel, noTmpl string) bool {
	// Project-level user-owned skeletons.
	switch noTmpl {
	case "providers.go", "app-auth.go", "middleware.go", "tools.go", "config.proto",
		"example.proto", "user-example.proto",
		"docker-compose.yml":
		return true
	case "README.md", "README.cli.md", "README.library.md",
		"CONTRIBUTING.md", "CHANGELOG.md", "CODEOWNERS",
		"db-README.md", "examples-README.md",
		"pkg-app-CONVENTIONS.md", "golangci.yml":
		return true
	}
	// Service-package user-owned files.
	if strings.Contains(rel, "internal/templates/service/") {
		switch noTmpl {
		case "service.go", "handlers.go":
			return true
		}
	}
	// (The thin auth-policy pair: project/middleware.go.tmpl is rendered —
	// it declares the project-scoped session cookie name — and is user-owned
	// from birth, so it is listed with app-auth.go in isKnownTier3;
	// middleware_test.go stays plain .go, which the banner walk never
	// reaches. Mechanisms live in forge/pkg/{authn,middleware}.)
	// Worker scaffolds (worker.go.tmpl / worker_test.go.tmpl + cron variants).
	if strings.Contains(rel, "internal/templates/worker/") ||
		strings.Contains(rel, "internal/templates/worker-cron/") {
		return true
	}
	// Webhook scaffolds (user-owned routes/store/test).
	if strings.Contains(rel, "internal/templates/webhook/") &&
		noTmpl != "webhook_routes_gen.go" {
		return true
	}
	// Operator + CRD shells.
	if strings.Contains(rel, "internal/templates/operator/") ||
		strings.Contains(rel, "internal/templates/crd/") {
		return true
	}
	// E2E tests.
	if strings.Contains(rel, "internal/templates/test/e2e/") {
		return true
	}
	// KCL deploy environments — multi-env infra config; user-owned after first emit.
	if strings.Contains(rel, "internal/templates/deploy/kcl/") {
		return true
	}
	// Frontend Next.js / RN / Vite SPA page scaffolds + connect/nav/layout,
	// plus the cross-tree roots those trees compose with (frontend/shared,
	// frontend/shared-web — see templates.FrontendTemplateRoots).
	if strings.Contains(rel, "internal/templates/frontend/nextjs/") ||
		strings.Contains(rel, "internal/templates/frontend/react-native/") ||
		strings.Contains(rel, "internal/templates/frontend/vite-spa/") ||
		strings.Contains(rel, "internal/templates/frontend/vite-spa-pages/") ||
		strings.Contains(rel, "internal/templates/frontend/shared/") ||
		strings.Contains(rel, "internal/templates/frontend/shared-web/") {
		return true
	}
	return false
}
